<script lang="ts" module>
  import type { IconName } from './icons';

  /** 官方 SVG 的尺寸与 viewBox (20x20, 见包内文件)。 */
  const ICON_BOX = 20;

  interface IconPath {
    d: string;
    fillRule?: 'nonzero' | 'evenodd';
  }

  /**
   * 从官方 SVG 源码里取出全部 `<path>` 的 `d` 与 `fill-rule`。
   *
   * 包内 20px 图标格式统一, 因此这个解析足够可靠; 万一格式变了, `tests/icons.test.ts` 会暴露。
   * 未知的 `fill-rule` 取值一律退回 `nonzero` (SVG 的默认值)。
   */
  export function pathsOf(svg: string): IconPath[] {
    return [...svg.matchAll(/<path\b([^>]*)\/?>/g)].map((match) => {
      const attrs = match[1];
      const d = /\bd="([^"]*)"/.exec(attrs)?.[1] ?? '';
      const fillRule = /\bfill-rule="([^"]*)"/.exec(attrs)?.[1];
      return fillRule === 'evenodd' ? { d, fillRule } : { d };
    });
  }
</script>

<script lang="ts">
  import { ICON_SVG } from './icons';

  let {
    /** 语义图标名 (Fluent 图标名去掉 Regular/Filled 后缀) */
    name,
    /** 边长。省略时继承字号, 传数字则按 px */
    size,
  }: {
    name: IconName;
    size?: number;
  } = $props();

  const paths = $derived(pathsOf(ICON_SVG[name]));
</script>

<svg
  xmlns="http://www.w3.org/2000/svg"
  width={size === undefined ? '1em' : `${size}px`}
  height={size === undefined ? '1em' : `${size}px`}
  viewBox="0 0 {ICON_BOX} {ICON_BOX}"
  fill="currentColor"
  focusable="false"
  aria-hidden="true"
  class="icon"
>
  {#each paths as path, index (index)}
    <path d={path.d} fill-rule={path.fillRule ?? 'nonzero'} />
  {/each}
</svg>
